# Function to get SIDHistory of all users and groups in the domain
function Get-SIDHistory {
    $SIDHistory = @()

    # Get all users and groups in the domain
    $domain = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()
    $users = $domain.GetUsers()
    $groups = $domain.GetGroups()

    foreach ($user in $users) {
        $userSID = $user.Sid.Value
        $userSIDHistory = $user.SidHistory
        if ($userSIDHistory) {
            foreach ($sid in $userSIDHistory) {
                $SIDHistory += [PSCustomObject]@{
                    OldSID = $sid
                    NewSID = $userSID
                }
            }
        }
    }

    foreach ($group in $groups) {
        $groupSID = $group.Sid.Value
        $groupSIDHistory = $group.SidHistory
        if ($groupSIDHistory) {
            foreach ($sid in $groupSIDHistory) {
                $SIDHistory += [PSCustomObject]@{
                    OldSID = $sid
                    NewSID = $groupSID
                }
            }
        }
    }

    return $SIDHistory
}

# Function to save SIDHistory to a file
function Save-SIDHistory {
    param (
        [Parameter(Mandatory = $true)]
        [System.Collections.Generic.List[PSCustomObject]]$SIDHistory
    )

    $SIDHistory | Export-Csv -Path $SIDHistoryFile -NoTypeInformation
    Write-Host "SIDHistory saved to $SIDHistoryFile"
}

