```csharp
public class LoanAggregate : AggregateRoot
{
    public Guid LoanId { get; private set; }
    public LoanStatus Status { get; private set; }
    public DateTime LastUpdatedTime { get; private set; }
    public List<Qualification> Qualifications { get; private set; }

    public LoanAggregate(Guid loanId)
    {
        LoanId = loanId;
        Qualifications = new List<Qualification>();
    }

    public void Apply(LoanStatusUpdateEvent @event)
    {
        if (@event.Timestamp < LastUpdatedTime)
        {
            throw new InvalidOperationException("Cannot apply event with timestamp earlier than current time.");
        }

        Status = @event.Status;
        LastUpdatedTime = @event.Timestamp;
    }

    public void Apply(QualificationChangedEvent @event)
    {
        var qualification = Qualifications.FirstOrDefault(q => q.Domain == @event.Domain);
        if (qualification == null)
        {
            qualification = new Qualification(@event.Domain);
            Qualifications.Add(qualification);
        }

        qualification.Apply(@event);
    }

    public void UpdateStatus(LoanStatus newStatus, DateTime commandTime)
    {
        if (commandTime < LastUpdatedTime)
        {
            throw new InvalidOperationException("Command time is earlier than the last update time.");
        }

        var @event = new LoanStatusUpdateEvent
        {
            LoanIdentifier = LoanId,
            Status = newStatus,
            Timestamp = commandTime
        };

        Apply(@event);
        AddDomainEvent(@event);
    }

    public void UpdateQualification(string domain, QualificationStatus status, DateTime commandTime)
    {
        if (commandTime < LastUpdatedTime)
        {
            throw new InvalidOperationException("Command time is earlier than the last update time.");
        }

        var @event = new QualificationChangedEvent
        {
            LoanIdentifier = LoanId,
            Domain = domain,
            Status = status,
            Timestamp = commandTime
        };

        Apply(@event);
        AddDomainEvent(@event);
    }
}
```

